//! MCP over streamable HTTP on the loopback interface (feature `http`).
//!
//! The endpoint is `http://127.0.0.1:<port>/mcp`. Every request must carry `Authorization: Bearer <token>` (the token is
//! generated by the caller, usually with [`crate::server::generate_token`]); `Host` headers other than loopback names are
//! refused by rmcp (DNS-rebinding protection), and the listener is bound to `127.0.0.1` only.

use std::net::{Ipv4Addr, SocketAddr};

use axum::extract::Request;
use axum::http::{HeaderMap, StatusCode, header};
use axum::middleware::{self, Next};
use axum::response::{IntoResponse as _, Response};
use rmcp::transport::streamable_http_server::session::local::LocalSessionManager;
use rmcp::transport::streamable_http_server::{StreamableHttpServerConfig, StreamableHttpService};

use crate::front::AnimMcp;
use crate::serve::ServeError;
use crate::wire::tokens_match;

/// A bound HTTP listener, ready to serve.
#[derive(Debug)]
pub struct HttpListener {
    listener: tokio::net::TcpListener,
    addr: SocketAddr,
}

impl HttpListener {
    /// Binds `127.0.0.1:port` (0 picks a free port).
    ///
    /// # Errors
    /// [`ServeError`] when the port cannot be bound.
    pub async fn bind(port: u16) -> Result<Self, ServeError> {
        let listener =
            tokio::net::TcpListener::bind((Ipv4Addr::LOCALHOST, port)).await.map_err(|e| ServeError::new(format!("could not bind 127.0.0.1:{port}: {e}")))?;
        let addr = listener.local_addr().map_err(|e| ServeError::new(e.to_string()))?;
        Ok(Self { listener, addr })
    }

    /// The bound address.
    #[must_use]
    pub const fn addr(&self) -> SocketAddr {
        self.addr
    }

    /// The URL clients use.
    #[must_use]
    pub fn url(&self) -> String {
        format!("http://{}/mcp", self.addr)
    }
}

async fn require_token(headers: HeaderMap, request: Request, next: Next, token: String) -> Response {
    let presented = headers.get(header::AUTHORIZATION).and_then(|v| v.to_str().ok()).and_then(|v| v.strip_prefix("Bearer ")).unwrap_or_default();
    if tokens_match(presented, &token) { next.run(request).await } else { (StatusCode::UNAUTHORIZED, "missing or wrong bearer token").into_response() }
}

/// Serves `mcp` on `listener` until `shutdown` completes.
///
/// # Errors
/// [`ServeError`] when the server fails.
pub async fn serve_http<S>(mcp: AnimMcp, listener: HttpListener, token: String, shutdown: S) -> Result<(), ServeError>
where
    S: std::future::Future<Output = ()> + Send + 'static,
{
    // rmcp's session manager is shared between its connections and its API takes it in an `Arc`.
    #[expect(clippy::disallowed_types, reason = "StreamableHttpService::new takes the session manager as Arc<M>")]
    let sessions = std::sync::Arc::new(LocalSessionManager::default());
    let service = StreamableHttpService::new(move || Ok(mcp.clone()), sessions, StreamableHttpServerConfig::default());
    let router = axum::Router::new()
        .nest_service("/mcp", service)
        .layer(middleware::from_fn(move |headers, request, next| require_token(headers, request, next, token.clone())));
    axum::serve(listener.listener, router).with_graceful_shutdown(shutdown).await.map_err(|e| ServeError::new(e.to_string()))
}
